INSERT INTO "restaurants" ("id", "slug", "name", "cuisine", "address", "phone", "main_image_url", "logo_url", "average_rating", "price_range", "description", "opening_hours", "latitude", "longitude", "specialties", "status") VALUES
('00000000-0000-4000-8000-000000000001', 'chez-maman-cherie', 'Chez Maman Chérie', 'Congolaise Traditionnelle', 'Avenue Mobutu, Lubumbashi', '+243 997 123 456', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=400', 'https://images.unsplash.com/photo-1584463609561-6b65e9b7c63d?w=200&h=200&fit=crop', 4.8, '15-25 USD', 'Restaurant familial servant des plats traditionnels congolais dans une ambiance chaleureuse.', '11h00 - 22h00', -11.6702, 27.4689, ARRAY['Fufu','Pondu','Poisson salé','Chikwangue'], 'published'),
('00000000-0000-4000-8000-000000000002', 'le-baobab-dore', 'Le Baobab Doré', 'Africaine Fusion', 'Quartier Golf, Lubumbashi', '+243 998 234 567', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=400', 'https://images.unsplash.com/photo-1604147706283-d7113f3e720d?w=200&h=200&fit=crop', 4.6, '20-35 USD', 'Cuisine africaine moderne avec une touche contemporaine, terrasse avec vue panoramique.', '12h00 - 23h00', -11.6554, 27.4867, ARRAY['Tilapia grillé','Riz jollof','Brochettes de bœuf','Plantain caramélisé'], 'published'),
('00000000-0000-4000-8000-000000000003', 'saveurs-du-katanga', 'Saveurs du Katanga', 'Locale Katangaise', 'Avenue Lumumba, Centre-ville', '+243 999 345 678', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=400', 'https://images.unsplash.com/photo-1515165562835-c3b8e3b6a1b8?w=200&h=200&fit=crop', 4.7, '12-20 USD', 'Spécialités du Katanga dans un cadre authentique avec musique traditionnelle.', '10h00 - 21h00', -11.6631, 27.4752, ARRAY['Chenilles grillées','Kapenta','Ugali','Bière Primus'], 'published'),
('00000000-0000-4000-8000-000000000004', 'la-terrasse-tropicale', 'La Terrasse Tropicale', 'Internationale', 'Quartier Résidentiel, Lubumbashi', '+243 997 456 789', 'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=400', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=200&h=200&fit=crop', 4.5, '25-40 USD', 'Restaurant haut de gamme avec terrasse tropicale, cuisine internationale et africaine.', '18h00 - 24h00', -11.6488, 27.5024, ARRAY['Steaks','Fruits de mer','Salades exotiques','Cocktails tropicaux'], 'published'),
('00000000-0000-4000-8000-000000000005', 'mama-africa', 'Mama Africa', 'Pan-Africaine', 'Avenue des Martyrs, Lubumbashi', '+243 998 567 890', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=400', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=200&h=200&fit=crop', 4.9, '18-30 USD', 'Voyage culinaire à travers l''Afrique avec des plats de différents pays du continent.', '11h30 - 22h30', -11.6765, 27.4598, ARRAY['Tagine marocain','Injera éthiopien','Bobotie sud-africain','Thieboudienne'], 'published'),
('00000000-0000-4000-8000-000000000006', 'le-palmier-royal', 'Le Palmier Royal', 'Grillades & BBQ', 'Route de Kipushi, Lubumbashi', '+243 999 678 901', 'https://images.unsplash.com/photo-1544025162-d76694265947?w=400', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=200&h=200&fit=crop', 4.4, '15-28 USD', 'Spécialiste des grillades en plein air avec jardin tropical et animations musicales.', '16h00 - 23h00', -11.6893, 27.4416, ARRAY['Brochettes mixtes','Porc grillé','Poisson braisé','Légumes grillés'], 'published')
